public class RequestLoggingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger _logger;

    public async Task InvokeAsync(HttpContext context)
    {
        var body = await new StreamReader(context.Request.Body).ReadToEndAsync();
        _logger.LogInformation("Request: {Method} {Path} Body: {Body}",
            context.Request.Method,
            context.Request.Path,
            body);

        await _next(context);
    }
}

public class RedactingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger _logger;

    public async Task InvokeAsync(HttpContext context)
    {
        var request = context.Request;
        var sensitiveHeaders = new[] { "Authorization", "Cookie", "X-Api-Key" };

        var headers = request.Headers
            .Where(h => !sensitiveHeaders.Contains(h.Key))
            .ToDictionary(h => h.Key, h => h.Value.ToString());

        _logger.LogInformation("HTTP {Method} {Path} from {RemoteIp}",
            request.Method,
            request.Path,
            context.Connection.RemoteIpAddress);

        await _next(context);
    }
}
